import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import axios from "axios";

function ProductList() {
  // 1. Khai báo các State lưu trữ dữ liệu
  const [products, setProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [category, setCategory] = useState("");

  // 2. Gọi API lấy danh sách sản phẩm khi vừa vào trang hoặc khi đổi danh mục Filter
  useEffect(() => {
    // Tạm thời để localhost:8000, lát nữa cần thay bằng port thật của Backend
    let apiUrl = "http://localhost:8000/products";
    
    // Nếu người dùng có chọn filter danh mục thì thêm vào đuôi URL
    if (category) {
      apiUrl = `http://localhost:8000/products?category=${category}`;
    }

    axios.get(apiUrl)
      .then((response) => {
        setProducts(response.data);
      })
      .catch((error) => {
        console.error("Lỗi khi lấy danh sách sản phẩm:", error);
      });
  }, [category]); // Cứ mỗi khi 'category' thay đổi, useEffect này sẽ tự chạy lại

  // 3. Hàm xử lý khi người dùng bấm nút Tìm kiếm
  const handleSearch = (e) => {
    e.preventDefault(); // Ngăn trình duyệt load lại trang khi submit form
    
    // Gọi API GET /search
    axios.get(`http://localhost:8000/search?keyword=${searchTerm}`)
      .then((response) => {
        setProducts(response.data);
      })
      .catch((error) => {
        console.error("Lỗi khi tìm kiếm:", error);
      });
  };

  return (
    <div className="container mt-4">
      <h2 className="mb-4">Danh sách sản phẩm</h2>

      {/* --- KHU VỰC TÌM KIẾM VÀ LỌC --- */}
      <form onSubmit={handleSearch} className="row mb-4">
        {/* Ô Tìm kiếm */}
        <div className="col-md-8 d-flex">
          <input
            type="text"
            className="form-control me-2"
            placeholder="Nhập tên sản phẩm cần tìm..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <button type="submit" className="btn btn-primary">Tìm</button>
        </div>
        
        {/* Ô Lọc danh mục */}
        <div className="col-md-4">
          <select
            className="form-select"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
          >
            <option value="">Tất cả danh mục</option>
            <option value="DienThoai">Điện thoại</option>
            <option value="Laptop">Laptop</option>
          </select>
        </div>
      </form>

      {/* --- KHU VỰC HIỂN THỊ SẢN PHẨM --- */}
      <div className="row">
        {products.length > 0 ? (
          products.map((item) => (
            <div className="col-md-3 mb-4" key={item.id}>
              <div className="card h-100 shadow-sm">
                <img 
                  src={item.image || "https://via.placeholder.com/200"} 
                  className="card-img-top" 
                  alt={item.name} 
                />
                <div className="card-body d-flex flex-column">
                  <h5 className="card-title">{item.name}</h5>
                  <p className="card-text text-danger fw-bold">{item.price} VNĐ</p>
                  
                  {/* Nút chuyển sang trang chi tiết, truyền id (hoặc slug) của sản phẩm lên URL */}
                  <Link to={`/products/${item.slug || item.id}`} className="btn btn-outline-dark mt-auto w-100">
                    Xem chi tiết
                  </Link>
                </div>
              </div>
            </div>
          ))
        ) : (
          <p className="text-center mt-5">Đang tải dữ liệu hoặc không tìm thấy sản phẩm phù hợp.</p>
        )}
      </div>
    </div>
  );
}

export default ProductList;
